import org.apache.commons.lang.Validate;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNotSame;

public class FastDateFormat_getDateTimeInstance_TriageGen1Test {

    @Test
    public void testGetDateTimeInstance_AllParamsProvided() {
        int dateStyle = Calendar.LONG;
        int timeStyle = Calendar.SHORT;
        TimeZone tz = TimeZone.getTimeZone("GMT");
        Locale locale = Locale.US;

        FastDateFormat format1 = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, tz, locale);
        assertNotNull(format1);
        assertEquals(tz, format1.getTimeZone());
        assertEquals(locale, format1.getLocale());

        // Test caching mechanism: same params should return same instance
        FastDateFormat format2 = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, tz, locale);
        assertNotSame("Should return cached instance", format1, format2); // Note: If the cache uses the same key, they should be same. 
        // Actually, based on the code: format = cDateTimeInstanceCache.get(key); if null... put.
        // So format1 and format2 SHOULD be the same instance.
        assertEquals("Should return the exact same instance from cache", format1, format2);
    }










}

